// -- Route metadata (per-YAML file) --

export interface LandingRoute {
  language: string
  name: string
  label: string
  lang?: string
  useCase: string
}

// -- Lookup types (generated by build script) --

export interface LookupRoute {
  file: string
  language: string
  useCase: string
}

export interface LookupAlternate {
  name: string
  lang?: string
  hreflang: string
}

export interface LookupPage {
  label: string
  href: string
}

export interface Lookup {
  routes: Record<string, LookupRoute>
  alternates: Record<string, LookupAlternate[]>
  pages: LookupPage[]
}

// -- Landing page content model --

export interface LandingExample {
  title: string
  prompt: string
  slug?: string
  featured?: boolean
}

export interface LandingHeroData {
  title: string
  subtitle: string
  placeholders: string[]
  placeholdersMobile?: string[]
  examples: LandingExample[]
  scrollLabel?: string
  disclaimer?: boolean
}

export interface LandingExplainerData {
  type: 'explainer'
  id?: string
  preTitle?: string
  title: string
  text: string
  image: string
  imageSmall?: string
  imagePosition: 'left' | 'right'
}

export interface LandingFeaturesData {
  type: 'features'
  id?: string
  items: {
    title: string
    description: string
  }[]
}

export interface LandingFAQData {
  type: 'faq'
  id?: string
  title: string
  items: {
    question: string
    answer: string
  }[]
}

export interface LandingHelpData {
  type: 'help'
  id?: string
  title: string
  text: string
  ctaText: string
  ctaUrl: string
}

export type LandingSection =
  | LandingExplainerData
  | LandingFeaturesData
  | LandingFAQData
  | LandingHelpData

export interface LandingTheme {
  backgroundGradient?: 'default' | string
  glowColors?: [string, string, string, string, string]
  featureColors?: [string, string, string]
  accentColor?: string
}

export interface LandingHeaderData {
  showLogo?: boolean
  location: string
}

export interface LandingMeta {
  title: string
  description: string
}

export interface LandingPageData {
  route: LandingRoute
  meta: LandingMeta
  theme?: LandingTheme
  header: LandingHeaderData
  hero: LandingHeroData
  sections: LandingSection[]
}
